using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search API) for production use.
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") && q.Contains("2026") =>
                """
                1. "Quantum Computing Breakthroughs in 2026" - Nature Tech Review
                   IBM and Google have demonstrated quantum processors exceeding 4,000 qubits with error
                   correction rates below 0.01%. Practical quantum advantage has been shown in drug
                   discovery and materials science applications.

                2. "The State of Quantum Computing Mid-2026" - MIT Technology Review
                   Major cloud providers now offer quantum-as-a-service. Microsoft's topological
                   qubits have achieved record coherence times. Hybrid classical-quantum algorithms
                   are being used in production for optimization problems in logistics.

                3. "Quantum Computing Market Report 2026" - Gartner
                   The quantum computing market is projected to reach $8.6 billion by end of 2026.
                   Key players include IBM, Google, Microsoft, IonQ, and Rigetti. Enterprise adoption
                   has grown 340% year-over-year.
                """,
            var q when q.Contains("quantum") && q.Contains("error correction") =>
                """
                1. "Fault-Tolerant Quantum Computing Achieved" - Science Daily
                   Researchers have demonstrated logical qubits with error rates 10x below the
                   threshold needed for practical computation. Surface codes and color codes are
                   the leading error correction approaches.

                2. "Quantum Error Correction: From Theory to Practice" - arxiv.org
                   New hybrid error correction schemes combine hardware-level noise reduction with
                   software-based syndrome decoding, achieving 99.99% gate fidelity.
                """,
            var q when q.Contains("quantum") && q.Contains("application") =>
                """
                1. "Real-World Quantum Applications in 2026" - IEEE Spectrum
                   Quantum computing is now used in: cryptography (post-quantum transitions),
                   pharmaceutical drug discovery (protein folding), financial modeling (portfolio
                   optimization), and climate modeling (atmospheric simulations).

                2. "Quantum Machine Learning Shows Promise" - DeepMind Blog
                   Quantum-enhanced ML models outperform classical models for specific molecular
                   property predictions and combinatorial optimization tasks.
                """,
            _ =>
                $"""
                1. "General Information on: {query}" - Wikipedia
                   Overview article covering the main aspects of the topic.

                2. "Recent Developments in {query}" - TechCrunch
                   News coverage of the latest developments and industry trends.

                3. "Expert Analysis: {query}" - Research Institute
                   In-depth analysis from domain experts.
                """
        };

        return results;
    }
}

class NoteTakingTool
{
    private static readonly List<string> _notes = [];

    [Description("Saves a research note for later use in the summary. Use this to record key findings.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total notes)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n\n---\n\n", _notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
    }
}

// --- Main Program ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing breakthroughs in 2026";

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine($"Researching topic: {topic}");
Console.WriteLine(new string('─', 50));

// Configure the AI client - uses OPENAI_API_KEY and optionally OPENAI_BASE_URL env vars.
var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

var clientOptions = new OpenAIClientOptions();
if (!string.IsNullOrEmpty(endpoint))
    clientOptions.Endpoint = new Uri(endpoint);

var openAiClient = new OpenAIClient(apiKey, clientOptions);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Register tools with the chat client.
var tools = new[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(NoteTakingTool.SaveNote),
    AIFunctionFactory.Create(NoteTakingTool.GetNotes),
};

var chatOptions = new ChatOptions
{
    Tools = [.. tools],
    ToolMode = ChatToolMode.Auto,
};

// Agent system prompt that instructs the model to research and summarize.
var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to thoroughly research a topic by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Saving key findings as notes using the note-taking tool
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary

        Always perform at least 2-3 different searches to get a well-rounded understanding.
        Save important findings as notes before writing your final summary.
        End with a clear, structured summary of your research.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

// Agent loop - continues until the model stops requesting tool calls.
Console.WriteLine("\nAgent is working...\n");

const int maxIterations = 15;
for (var i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);

    // Add the response messages to the conversation history.
    messages.AddRange(response.Messages);

    // Check if there are any tool calls to process - if not, we're done.
    if (response.Messages.All(m => m.Role != ChatRole.Tool))
    {
        // Final response from the agent.
        Console.WriteLine("\n" + new string('═', 50));
        Console.WriteLine("RESEARCH SUMMARY");
        Console.WriteLine(new string('═', 50));
        var finalContent = string.Join("", response.Messages
            .Where(m => m.Role == ChatRole.Assistant)
            .SelectMany(m => m.Contents.OfType<TextContent>())
            .Select(tc => tc.Text));
        Console.WriteLine(finalContent);
        break;
    }

    if (i == maxIterations - 1)
    {
        Console.WriteLine("\n[Agent reached maximum iterations]");
    }
}

Console.WriteLine("\nResearch complete.");

