// --- Main Program ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing breakthroughs in 2026";

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine($"Researching topic: {topic}");
