 using System.ClientModel;
 using System.ComponentModel;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Main Program ---

 var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing breakthroughs in 2026";

 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║       AI Research Agent              ║");
 Console.WriteLine("╚══════════════════════════════════════╝");
 Console.WriteLine();
 Console.WriteLine($"Researching topic: {topic}");
 Console.WriteLine(new string('─', 50));

 // Configure the AI client - uses OPENAI_API_KEY and optionally OPENAI_BASE_URL env vars.
 var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "no-key";
 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

 var clientOptions = new OpenAIClientOptions();
 if (!string.IsNullOrEmpty(endpoint))
     clientOptions.Endpoint = new Uri(endpoint);

 var openAiClient = new OpenAIClient(new ApiKeyCredential(apiKey), clientOptions);
 IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

 // Register tools with the chat client.
 var tools = new[]
 {
     AIFunctionFactory.Create(WebSearchTool.SearchWeb),
     AIFunctionFactory.Create(NoteTakingTool.SaveNote),
     AIFunctionFactory.Create(NoteTakingTool.GetNotes),
 };

 var chatOptions = new ChatOptions
 {
     Tools = [.. tools],
     ToolMode = ChatToolMode.Auto,
 };

 // Agent system prompt that instructs the model to research and summarize.
 var messages = new List<ChatMessage>
 {
     new(ChatRole.System,
         """
         You are a research agent. Your job is to thoroughly research a topic by:
         1. Searching the web for relevant information (perform multiple searches with different queries)
         2. Saving key findings as notes using the note-taking tool
         3. After gathering enough information, retrieve your notes and provide a comprehensive summary

         Always perform at least 2-3 different searches to get a well-rounded understanding.
         Save important findings as notes before writing your final summary.
         End with a clear, structured summary of your research.
         """),
     new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
 };

 // Agent loop - continues until the model stops requesting tool calls.
 Console.WriteLine("\nAgent is working...\n");

 const int maxIterations = 15;
 for (var i = 0; i < maxIterations; i++)
 {
     var response = await chatClient.GetResponseAsync(messages, chatOptions);

     // Add the response messages to the conversation history.
     messages.AddRange(response.Messages);

     // Check if there are any tool calls to process - if not, we're done.
     if (response.Messages.All(m => m.Role != ChatRole.Tool))
     {
         // Final response from the agent.
         Console.WriteLine("\n" + new string('═', 50));
         Console.WriteLine("RESEARCH SUMMARY");
         Console.WriteLine(new string('═', 50));
         var finalContent = string.Join("", response.Messages
             .Where(m => m.Role == ChatRole.Assistant)
             .SelectMany(m => m.Contents.OfType<TextContent>())
             .Select(tc => tc.Text));
         Console.WriteLine(finalContent);
         break;
     }

     if (i == maxIterations - 1)
     {
         Console.WriteLine("\n[Agent reached maximum iterations]");
     }
 }

 Console.WriteLine("\nResearch complete.");

